if ~exist('src400sym','var')
    src400sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);lz 0 1;keep_figure; %[output:2502f792]
w2_000b = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 1; keep_figure; %[output:3179c6e2]

hc.log_level = ll;


othrEi400cut111 = {[-0.1,0.1],[-0.1,0.1],[0,2,250]};
file = src400sym.full_filename %[output:8e9da991]
[~,fname400] = fileparts(file);

% recover masks not to draw them again
[cuts2fit400GP,cuts_res_file]  = recover_selected_cuts('cuts2fit400GP','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
